import { buildingCode } from './labcode.ts';
// A plain string is not a LabCode. Pass it through toLabCode first.
export function buildingOf(raw: string): string {
  return buildingCode(raw);
}

export type LabCode = string & { readonly __brand: 'LabCode' };
const PATTERN = /^[A-Z]{2}-\d{3}$/;
export function toLabCode(raw: string): LabCode {
  if (!PATTERN.test(raw)) throw new Error('not a lab code: ' + raw);
  return raw as LabCode;
}
export function buildingCode(code: LabCode): string {
  return code.slice(0, 2);
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { buildingOf } from '../src/app.ts';
test('building of BE-201 is BE', () => { assert.equal(buildingOf('BE-201'), 'BE'); });

