import type { Slot } from './slot.ts';
// A free slot has no `by`. Narrow on `kind` before reading it.
export function whoHas(slot: Slot): string {
  return slot.by;
}

export type Slot =
  | { kind: 'free' }
  | { kind: 'booked'; by: string };
export const free: Slot = { kind: 'free' };
export const booked: Slot = { kind: 'booked', by: 'cuong' };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { whoHas } from '../src/app.ts';
import { free, booked } from '../src/slot.ts';
test('free slot has nobody', () => { assert.equal(whoHas(free), 'nobody'); });
test('booked slot names the booker', () => { assert.equal(whoHas(booked), 'cuong'); });

